/// Names of well-known generated files, excluded by default. Pass `--include-generated` to count these files.
const NAMES: &[&str] = &[
	// Lockfiles
	"Cargo.lock",
	"package-lock.json",
	"yarn.lock",
	"pnpm-lock.yaml",
	"bun.lockb",
	"bun.lock",
	"deno.lock",
	"go.sum",
	"Gemfile.lock",
	"composer.lock",
	"poetry.lock",
	"rebar.lock",
	"Pipfile.lock",
	"uv.lock",
	"mix.lock",
	"pubspec.lock",
	"flake.lock",
	"Podfile.lock",
	"packages.lock.json",
	"shrinkwrap.json",
	"cabal.project.freeze",
	"cpanfile.snapshot",
	"gradle.lockfile",
	".terraform.lock.hcl",
	// Eclipse's project files
	".classpath",
	".project",
	".cproject",
];

/// Extensions of files that tools write or keep: translations, which a tool extracts and merges, and what IDEs and interface designers save.
const EXTENSIONS: &[&str] = &[
	// Translations: Gettext, XLIFF, .NET resources, and Group Policy language files
	"po",
	"pot",
	"xliff",
	"xlf",
	"resx",
	"adml",
	// Visual Studio solutions and Visual C++ 2008 projects, ReSharper and IntelliJ settings
	"sln",
	"vcproj",
	"DotSettings",
	"iml",
	// Interface Builder, Qt Designer, and Glade
	"xib",
	"storyboard",
	"ui",
	"glade",
];

/// Endings that need more than an extension: minified assets, Visual Studio's filters, and per-user project settings.
const ENDINGS: &[&str] = &[
	".min.js",
	".min.mjs",
	".min.css",
	".vcxproj.filters",
	".csproj.user",
	".vbproj.user",
	".fsproj.user",
	".vcxproj.user",
];

/// Whether a file's name says it's generated: a lockfile, minified asset, translation, or what an IDE or interface designer saves. Matched here rather than as globs on the walk, which would cost every path a glob match.
pub fn is_generated_name(name: &str) -> bool {
	let Some((stem, extension)) = name.rsplit_once('.') else { return false };
	if stem.is_empty() {
		return NAMES.contains(&name);
	}
	match extension {
		"js" | "mjs" | "css" | "filters" | "user" => {
			ENDINGS.iter().any(|ending| name.len() > ending.len() && name.ends_with(ending))
		}
		_ => EXTENSIONS.contains(&extension) || NAMES.contains(&name),
	}
}

/// The namespace of the project files Visual Studio writes. SDK-style projects, which people write by hand, leave it out.
const VISUAL_STUDIO_NAMESPACE: &[u8] = b"schemas.microsoft.com/developer/msbuild/2003";

/// Whether a file is a project file Visual Studio wrote: a C# or Visual Basic project from before SDK-style projects, or any Visual C++ project, which list every source file and build configuration.
pub fn is_visual_studio_project(name: &str, bytes: &[u8]) -> bool {
	let project = [".csproj", ".vbproj", ".fsproj", ".vcxproj"].iter().any(|ending| name.ends_with(ending));
	project && memchr::memmem::find(&bytes[..bytes.len().min(HEADER_BYTES)], VISUAL_STUDIO_NAMESPACE).is_some()
}

use std::sync::LazyLock;

use memchr::memmem::Finder;

/// How far into a file a generated-file marker is looked for: past a license header, which often comes first.
const HEADER_LINES: usize = 30;
const HEADER_BYTES: usize = 4 * 1024;

/// Every generated-file marker holds "generat"; these find it in lower or upper case.
static LOWER: LazyLock<Finder<'static>> = LazyLock::new(|| Finder::new(b"enerat"));
static UPPER: LazyLock<Finder<'static>> = LazyLock::new(|| Finder::new(b"ENERAT"));

/// Whether a file's opening comments say it was generated, as in Go's `// Code generated by stringer. DO NOT EDIT.`, protoc's `// Generated by the protocol buffer compiler.  DO NOT EDIT!`, C#'s `<auto-generated>` or `@generated`. Only the comments before the first line of code are read, so code like Ruby's `@generated = x` doesn't count, and a file that starts with code costs next to nothing.
pub fn has_generated_header(bytes: &[u8]) -> bool {
	let header = &bytes[..bytes.len().min(HEADER_BYTES)];
	let end = opening_comments_end(header);
	// Every marker holds "generat", and nearly no file's opening comments do, so look for that first, as "enerat" or "ENERAT" with fast substring searches; mixed case isn't worth a slower search through every file.
	let opening = &header[..end];
	if LOWER.find(opening).is_none() && UPPER.find(opening).is_none() {
		return false;
	}
	let mut lines = Vec::new();
	opening_comments(header, |number, line| lines.push((number, line)));
	let says = |i: usize, test: fn(&[u8]) -> bool| lines.iter().any(|&(j, line)| i.abs_diff(j) <= 4 && test(line));
	// "Generated" and "do not edit" within a few lines of each other, as in `This makefile was generated by bakefile.` over `Do not modify`, but not a mention of generated bytecode far from a request not to change an API.
	lines.iter().any(|&(i, line)| {
		marks_generated(line) || (says_do_not_edit(line) && says(i, |line| contains_ignoring_case(line, b"generated")))
	})
}

fn says_do_not_edit(line: &[u8]) -> bool {
	[b"do not edit".as_slice(), b"don't edit", b"do not modify"]
		.iter()
		.any(|phrase| contains_ignoring_case(line, phrase))
}

/// Block comment and docstring delimiters, whose lines between count as comment lines even without a marker of their own.
const BLOCKS: &[(&[u8], &[u8])] =
	&[(b"/*", b"*/"), (b"\"\"\"", b"\"\"\""), (b"'''", b"'''"), (b"{-", b"-}"), (b"(*", b"*)"), (b"<!--", b"-->")];

/// Visit the comment lines a header opens with, numbered, and return where they end: lines starting the way comments do in most languages (`//`, `#`, `/*`, ` * `, `--`, `;`, `%`, `'`, `<!--`), and lines inside a block comment or docstring one of them opened, up to the first line of code. Blank lines are skipped.
fn opening_comments<'a>(header: &'a [u8], mut visit: impl FnMut(usize, &'a [u8])) -> usize {
	let mut open: Option<&[u8]> = None;
	let mut start = 0;
	let mut end = 0;
	for number in 0..HEADER_LINES {
		if start >= header.len() {
			break;
		}
		let line_end = memchr::memchr(b'\n', &header[start..]).map_or(header.len(), |i| start + i);
		let line = &header[start..line_end];
		let next = line_end + 1;
		let trimmed = line.trim_ascii_start();
		let trimmed = trimmed.strip_prefix("\u{FEFF}".as_bytes()).unwrap_or(trimmed);
		if let Some(close) = open {
			if contains(trimmed, close) {
				open = None;
			}
		} else if trimmed.is_empty() {
			start = next;
			continue;
		} else {
			// A lone `"` starts a string more often than a comment (Vim's), but `"""` is a docstring.
			let starts_comment =
				trimmed.first().is_some_and(|b| COMMENT_STARTS.contains(b)) || trimmed.starts_with(b"\"\"\"");
			if !starts_comment {
				break;
			}
			if let Some(&(opener, close)) = BLOCKS.iter().find(|(opener, _)| starts_with(trimmed, opener))
				&& !contains(&trimmed[opener.len()..], close)
			{
				open = Some(close);
			}
		}
		visit(number, line);
		end = line_end;
		start = next;
	}
	end
}

/// Where the comments a header opens with end, found quickly by jumping over whole block comments, so nearly every file can be ruled out before its lines are looked at one by one.
fn opening_comments_end(header: &[u8]) -> usize {
	let mut pos = 0;
	loop {
		pos += header[pos..].iter().take_while(|b| b.is_ascii_whitespace()).count();
		let rest = &header[pos..];
		let rest = rest.strip_prefix("\u{FEFF}".as_bytes()).unwrap_or(rest);
		pos = header.len() - rest.len();
		if !rest.first().is_some_and(|b| COMMENT_STARTS.contains(b)) && !starts_with(rest, b"\"\"\"") {
			return pos;
		}
		if let Some(&(opener, close)) = BLOCKS.iter().find(|(opener, _)| starts_with(rest, opener)) {
			let Some(found) = find(&rest[opener.len()..], close) else {
				return header.len();
			};
			pos += opener.len() + found + close.len();
		} else {
			pos = memchr::memchr(b'\n', rest).map_or(header.len(), |i| pos + i + 1);
		}
	}
}

/// The first characters of comment lines in most languages.
const COMMENT_STARTS: &[u8] = b"/*#-;%'<!({:";

/// `haystack.starts_with(needle)` for a needle of a few bytes, comparing them inline rather than calling `memcmp`.
fn starts_with(haystack: &[u8], needle: &[u8]) -> bool {
	haystack.len() >= needle.len() && haystack.iter().zip(needle).all(|(a, b)| a == b)
}

/// Where the short `needle` first is in `haystack`, without the setup a substring searcher costs.
fn find(haystack: &[u8], needle: &[u8]) -> Option<usize> {
	// Comparing byte by byte, as delimiters are a few bytes long, saves a call to `memcmp` at every candidate, like each ` * ` of a license header.
	memchr::memchr_iter(needle[0], haystack).find(|&i| starts_with(&haystack[i..], needle))
}

fn contains(haystack: &[u8], needle: &[u8]) -> bool {
	find(haystack, needle).is_some()
}

/// Whether a comment line names the file generated: `@generated`, `<auto-generated>`, or "automatically generated" and the like with a word saying what, so "an auto-generated key" in a doc comment doesn't count.
fn marks_generated(line: &[u8]) -> bool {
	const SOFT: &[&[u8]] =
		&[b"automatically generated", b"auto-generated", b"autogenerated", b"machine generated", b"machine-generated"];
	const CONTEXT: &[&[u8]] = &[b"this ", b"by ", b"from ", b"on ", b"do not", b"don't"];
	contains_ignoring_case(line, b"@generated")
		|| contains_ignoring_case(line, b"<auto-generated")
		|| contains_ignoring_case(line, b"< auto-generated")
		|| (SOFT.iter().any(|marker| contains_ignoring_case(line, marker))
			&& CONTEXT.iter().any(|word| contains_ignoring_case(line, word)))
}

/// Whether `haystack` contains `needle`, ignoring ASCII case. `needle` must be lowercase.
fn contains_ignoring_case(haystack: &[u8], needle: &[u8]) -> bool {
	let first = needle[0];
	memchr::memchr2_iter(first, first.to_ascii_uppercase(), haystack)
		.any(|i| haystack.get(i..i + needle.len()).is_some_and(|candidate| candidate.eq_ignore_ascii_case(needle)))
}

#[cfg(test)]
mod tests {
	use rstest::rstest;

	use super::{has_generated_header, is_generated_name, is_visual_studio_project};

	#[rstest]
	#[case("Cargo.lock", true)]
	#[case(".project", true)]
	#[case("app.min.js", true)]
	#[case(".min.js", false)]
	#[case("app.js", false)]
	#[case("de.po", true)]
	#[case("changes.xliff", true)]
	#[case("Strings.resx", true)]
	#[case("wx.sln", true)]
	#[case("wx.sln.DotSettings", true)]
	#[case("MainMenu.xib", true)]
	#[case("Main.storyboard", true)]
	#[case("dialog.ui", true)]
	#[case("lib.vcxproj.filters", true)]
	#[case("App.csproj.user", true)]
	#[case("App.csproj", false)]
	#[case("lib.vcxproj", false)]
	#[case("Directory.Build.props", false)]
	#[case("readme.user", false)]
	#[case("po", false)]
	#[case(".po", false)]
	fn names_of_generated_files(#[case] name: &str, #[case] expected: bool) {
		assert_eq!(is_generated_name(name), expected, "{name}");
	}

	#[test]
	fn visual_studio_projects_carry_its_namespace() {
		let old = r#"<?xml version="1.0" encoding="utf-8"?>
<Project ToolsVersion="14.0" xmlns="http://schemas.microsoft.com/developer/msbuild/2003">"#;
		let sdk = "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <PropertyGroup>\n";
		assert!(is_visual_studio_project("lib.vcxproj", old.as_bytes()));
		assert!(is_visual_studio_project("App.csproj", old.as_bytes()));
		assert!(!is_visual_studio_project("App.csproj", sdk.as_bytes()));
		assert!(!is_visual_studio_project("Directory.Build.props", old.as_bytes()));
	}

	#[rstest]
	#[case::go("// Code generated by stringer -type=Kind; DO NOT EDIT.\n\npackage x\n", true)]
	#[case::go_after_license(
		"/*\nCopyright 2024 The Kubernetes Authors.\n\nLicensed under the Apache License.\n*/\n\n// Code generated by deepcopy-gen. DO NOT EDIT.\n\npackage v1\n",
		true
	)]
	#[case::protoc("// Generated by the protocol buffer compiler.  DO NOT EDIT!\n// source: a.proto\n", true)]
	#[case::csharp(
		"//------\n// <auto-generated>\n//     This code was generated by a tool.\n// </auto-generated>\n",
		true
	)]
	#[case::at_generated("// @generated by `cargo xtask codegen`\nfn main() {}\n", true)]
	#[case::bindgen("/* automatically generated by rust-bindgen 0.69.4 */\n", true)]
	#[case::split_over_lines("# This file is generated by tools/gen.py.\n# Do not edit it by hand.\n", true)]
	#[case::ruby_instance_variable(
		"class Column\n  def initialize(generated: nil)\n    @generated = generated\n  end\nend\n",
		false
	)]
	#[case::julia_macro("@generated function f(x)\n    :(x)\nend\n", false)]
	#[case::doc_comment_prose("/**\n * Retrieves the auto-generated key of the row.\n */\n", false)]
	#[case::bom("\u{FEFF}// <auto-generated />\nclass A {}\n", true)]
	#[case::sphinx("# Autogenerated by Sphinx on Tue Oct 1\ntopics = {}\n", true)]
	#[case::spaced_auto_generated("// Licensed under MIT.\n// < auto-generated />\n#nullable enable\n", true)]
	#[case::inside_block_comment(
		"/*\n IMPORTANT: this file is generated by gen.py from a.h.in.\n Do not edit it.\n*/\nint x;\n",
		true
	)]
	#[case::python_docstring(
		"\"\"\"Keywords\n\nThis file is automatically generated; please don't muck it up!\n\"\"\"\n",
		true
	)]
	#[case::block_comment_closed_before_code("/* tables */\n@generated = 1\n", false)]
	#[case::far_apart(
		"/*\n * Profiles dynamically generated bytecode.\n *\n *\n *\n *\n * Do not modify the function signatures.\n */\n",
		false
	)]
	#[case::generator_strings(
		"static const char *header =\n\"/* DO NOT MODIFY.\\n\"\n\" * This file was generated from rules\\n\";\n",
		false
	)]
	#[case::plain_code("fn main() {\n    let generated = 1;\n}\n", false)]
	#[case::mentions_generation("// Generates the lookup tables at build time.\nfn generate() {}\n", false)]
	#[case::generates_and_do_not_edit("// Generates the tables. DO NOT EDIT them by hand.\n", false)]
	#[case::do_not_edit_alone("// DO NOT EDIT below this line without asking.\nint x;\n", false)]
	#[case::marker_too_far_down(&format!("{}// Code generated. DO NOT EDIT.\n", "x = 1\n".repeat(40)), false)]
	fn detects_generated_headers(#[case] text: &str, #[case] expected: bool) {
		assert_eq!(has_generated_header(text.as_bytes()), expected);
	}
}
